(window.EXSUB_C=window.EXSUB_C||{})[25]={"a-5":[{"t":"PRINCIPIOS BÁSICOS DE ACTUACIÓN · 6 bloques (cuadro del temario · pág. 8 · art. 5)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>▦</i>PRINCIPIOS BÁSICOS DE ACTUACIÓN · 6 bloques (cuadro del temario · pág. 8 · art. 5)</div><div class=\"vis-tabla\"><div class=\"vt-cab\"><span>Principio</span><span>Texto de la ley</span></div><div class=\"vt-nodo\"><div class=\"vt-et o\"><mark class=\"m-destacable\"><u class=\"m-clave\">1 · ADECUACIÓN AL ORDENAMIENTO JURÍDICO</u></mark></div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">Ejercer su función con <mark class=\"m-personalizado\"><u class=\"m-clave\">absoluto respeto a la Constitución y al resto del Ordenamiento Jurídico</u></mark>.</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Actuar en el cumplimiento de sus funciones, con <mark class=\"m-personalizado\"><u class=\"m-clave\">absoluta neutralidad política e imparcialidad</u></mark> y, en consecuencia, <u class=\"m-clave\">sin</u> discriminación alguna por razón de raza, religión u opinión.</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Actuar con <mark class=\"m-personalizado\"><u class=\"m-clave\">integridad y dignidad</u></mark>. En particular debe abstenerse en todo acto de <mark class=\"m-destacable\">corrupción</mark> y oponerse a él resueltamente.</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Sujetarse en su actuación profesional, a los <mark class=\"m-personalizado\"><u class=\"m-clave\">principios de jerarquía y subordinación</u></mark>. <u class=\"m-clave\">En ningún caso</u>, la obediencia debida <mark class=\"m-accion\">podrá amparar</mark> órdenes que entrañen la ejecución de actos que manifiestamente constituyen delito o sean contrarios a la Constitución o a las Leyes.</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\"><mark class=\"m-personalizado\"><u class=\"m-clave\">Colaborar con la Administración de Justicia y auxiliarla</u></mark> en los términos establecidos en la Ley.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et v\"><mark class=\"m-destacable\"><u class=\"m-clave\">2 · RELACIONES CON LA COMUNIDAD</u></mark></div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\"><mark class=\"m-personalizado\"><u class=\"m-clave\">Impedir</u></mark>, en el ejercicio de su actuación profesional, <mark class=\"m-personalizado\"><u class=\"m-clave\">cualquier práctica abusiva, arbitraria o discriminatoria</u></mark> que entrañe violencia física o moral.</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Observar <mark class=\"m-personalizado\"><u class=\"m-clave\">en todo momento un trato correcto y esmerado</u></mark> en sus relaciones con los ciudadanos, a quienes procuraran auxiliar y proteger, <mark class=\"m-personalizado\"><u class=\"m-clave\">siempre que las circunstancias lo aconsejen o fueren requeridos para ello.</u></mark> En todas sus intervenciones, proporcionaran información cumplida, y tan amplia como sea posible, sobre las causas y finalidad de las mismas.</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">En el ejercicio de sus funciones <mark class=\"m-accion\">deberán actuar</mark> <mark class=\"m-destacable\">con la decisión necesaria, sin demora</mark> cuando de ello dependa evitar un <mark class=\"m-destacable\">daño grave, inmediato e irreparable</mark>; rigiéndose al hacerlo por los <mark class=\"m-destacable\">principios de congruencia, oportunidad y proporcionalidad</mark> en la utilización de los medio a su alcance.</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\"><mark class=\"m-destacable\"><u class=\"m-clave\">Solamente</u></mark> <mark class=\"m-accion\">deberán utilizar</mark> las armas en las situaciones en que exista un riesgo <mark class=\"m-destacable\">racionalmente grave</mark> para su vida, su integridad física o las de terceras <mark class=\"m-autoridad\">personas,</mark> o en aquellas circunstancias que puedan suponer un <mark class=\"m-destacable\">grave</mark> riesgo para la seguridad ciudadana y de conformidad con los principios a que se refiere el apartado anterior.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et c\"><mark class=\"m-destacable\"><u class=\"m-clave\">3 · TRATAMIENTO DE DETENIDOS</u></mark></div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">Los miembros de las Fuerzas y Cuerpos de Seguridad <mark class=\"m-accion\">deberán identificarse</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">debidamente</u></mark> como tales en el momento de efectuar una detención.</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\"><mark class=\"m-accion\">Velarán</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">por la vida e integridad física</u></mark> de las <mark class=\"m-autoridad\">personas</mark> a quienes detuvieren o que se encuentren bajo su custodia y <mark class=\"m-accion\">respetarán</mark> el honor y la dignidad de las <mark class=\"m-autoridad\">personas.</mark></div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\"><mark class=\"m-accion\">Darán</mark> cumplimiento y <mark class=\"m-accion\">observarán</mark> con la debida diligencia los <mark class=\"m-personalizado\"><u class=\"m-clave\">trámites, plazos y requisitos exigidos por el Ordenamiento Jurídico</u></mark>, cuando se proceda a la detención de una <mark class=\"m-autoridad\">persona.</mark></div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et a\"><mark class=\"m-destacable\"><u class=\"m-clave\">4 · DEDICACIÓN PROFESIONAL</u></mark></div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\"><mark class=\"m-accion\">Deberán llevar</mark> a cabo sus <mark class=\"m-personalizado\"><u class=\"m-clave\">funciones con total dedicación</u></mark>, debiendo intervenir siempre, en cualquier tiempo y lugar, <mark class=\"m-personalizado\"><u class=\"m-clave\">se hallen o no de servicio</u></mark>, en defensa de la Ley y de la seguridad ciudadana.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et o\"><mark class=\"m-destacable\"><u class=\"m-clave\">5 · SECRETO PROFESIONAL</u></mark></div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\"><mark class=\"m-accion\">Deberán guardar</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">riguroso secreto</u></mark> respecto a todas las informaciones que conozcan <mark class=\"m-personalizado\"><u class=\"m-clave\">por razón o con ocasión del desempeño de sus funciones</u></mark>. <mark class=\"m-accion\">No estarán obligados</mark> a revelar las fuentes de información <u class=\"m-clave\">salvo</u> que el ejercicio de sus funciones o las disposiciones de la Ley les impongan actuar de otra manera.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et v\"><mark class=\"m-destacable\"><u class=\"m-clave\">6 · RESPONSABILIDAD</u></mark></div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">Son responsables <mark class=\"m-destacable\">personal y directamente</mark> por los actos que en su actuación profesional llevaren a cabo, infringiendo o vulnerando las normas legales, así como las reglamentarias que rijan su profesión y los principios enunciados anteriormente, <u class=\"m-clave\">sin perjuicio</u> de la responsabilidad patrimonial que pueda corresponder a las <mark class=\"m-autoridad\">Administraciones Publicas</mark> por las mismas.</div></div></div></div></div></div>"}],"a-6":[{"t":"PRINCIPIOS (cuadro del temario · pág. 10 · art. 6.1 y 6.6 · cajas R3 y R4 de la pág. 9)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⇄</i>PRINCIPIOS (cuadro del temario · pág. 10 · art. 6.1 y 6.6 · cajas R3 y R4 de la pág. 9)</div><div class=\"vis-comp\" style=\"--n:2\"><div class=\"vis-col\"><h5><mark class=\"m-destacable\"><u class=\"m-clave\">PROMOCIÓN PROFESIONAL, SOCIAL Y HUMANA</u></mark></h5><ul><li><mark class=\"m-personalizado\">OBJETIVIDAD</mark></li><li><mark class=\"m-personalizado\">IGUALDAD DE OPORTUNIDADES</mark></li><li><mark class=\"m-personalizado\">MÉRITO</mark></li><li><mark class=\"m-personalizado\">CAPACIDAD</mark></li></ul></div><div class=\"vis-col\"><h5><mark class=\"m-destacable\"><u class=\"m-clave\">PROVISIÓN DE PUESTOS DE SERVICIO</u></mark></h5><ul><li><mark class=\"m-personalizado\">MÉRITO</mark></li><li><mark class=\"m-personalizado\">CAPACIDAD</mark></li><li><mark class=\"m-personalizado\">ANTIGÜEDAD</mark></li></ul></div></div></div>"}],"a-10":[{"t":"DE LAS FUERZAS Y CUERPOS DE SEGURIDAD DEL ESTADO · organigrama (cuadro del temario · pág. 12 · arts. 9-10)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>➜</i>DE LAS FUERZAS Y CUERPOS DE SEGURIDAD DEL ESTADO · organigrama (cuadro del temario · pág. 12 · arts. 9-10)</div><div class=\"vis-flujo\"><div class=\"vis-paso o\"><span class=\"et\">1º</span><mark class=\"m-autoridad\">MINISTRO DE INTERIOR</mark></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \">Le corresponde:</div><div class=\"vis-flecha\">↓</div><div class=\"vis-bifurca\"><div class=\"vis-paso v\"><mark class=\"m-personalizado\">Administración general de la seguridad ciudadana</mark></div><div class=\"vis-paso o\"><mark class=\"m-destacable\"><u class=\"m-clave\">MANDO SUPERIOR</u></mark> de las Fuerzas y Cuerpos de Seguridad del <mark class=\"m-autoridad\">Estado</mark></div><div class=\"vis-paso c\">Responsabilidad de las relaciones de <mark class=\"m-personalizado\">colaboración y auxilio</mark> con las <mark class=\"m-autoridad\">Autoridades policiales de otros países</mark> (conforme a lo establecido en Tratados y Acuerdos Internacionales)</div></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><mark class=\"m-personalizado\"><u class=\"m-clave\">Dicho mando</u></mark> <mark class=\"m-accion\">será ejercido</mark> en los términos establecidos en esta Ley por el:</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso o\"><span class=\"et\">2º</span><mark class=\"m-autoridad\">DIRECTOR DE LA SEGURIDAD DEL ESTADO</mark><br>• Bajo la <mark class=\"m-destacable\">inmediata</mark> <mark class=\"m-autoridad\">autoridad</mark> <mark class=\"m-destacable\">del Ministro del Interior</mark><br>• Del Director de la Seguridad del <mark class=\"m-autoridad\">Estado,</mark> dependen directamente:<br>&nbsp;&nbsp;◦ <mark class=\"m-autoridad\">Dirección General de la Guardia Civil</mark><br>&nbsp;&nbsp;◦ <mark class=\"m-autoridad\">Dirección General de la Policía</mark><br>• A través de las Direcciones Generales <mark class=\"m-accion\">coordinará</mark> <mark class=\"m-destacable\">la actuación</mark> de las Fuerzas y Cuerpos de Seguridad del <mark class=\"m-autoridad\">Estado</mark></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><mark class=\"m-personalizado\"><u class=\"m-clave\">En cada provincia:</u></mark></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso v\"><span class=\"et\">3º</span><mark class=\"m-autoridad\">GOBERNADOR CIVIL</mark><br>• <mark class=\"m-accion\">Ejercerá</mark> el <mark class=\"m-destacable\"><u class=\"m-clave\">MANDO DIRECTO</u></mark> de las Fuerzas y Cuerpos de Seguridad del <mark class=\"m-autoridad\">Estado</mark><br>• <mark class=\"m-accion\">Estará</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">sujeto a las directrices</u></mark> del:<br>&nbsp;&nbsp;◦ <mark class=\"m-autoridad\">Ministro del Interior</mark>, y<br>&nbsp;&nbsp;◦ <mark class=\"m-autoridad\">Director de la Seguridad del Estado</mark><br>• <u class=\"m-clave\">Sin perjuicio</u> de la <mark class=\"m-destacable\">dependencia funcional</mark> de las <mark class=\"m-destacable\">Unidades de Policía Judicial</mark>, respecto de los <mark class=\"m-autoridad\">Jueces, de los Tribunales y del Ministerio Fiscal</mark>, en sus funciones de averiguación del delito y descubrimiento y aseguramiento del delincuente.</div></div></div>"}],"a-12":[{"t":"FUNCIONES · comunes y reparto CNP / Guardia Civil (cuadro del temario · pág. 15 · arts. 11-12)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⇄</i>FUNCIONES · comunes y reparto CNP / Guardia Civil (cuadro del temario · pág. 15 · arts. 11-12)</div><div class=\"vis-comp\" style=\"--n:3\"><div class=\"vis-col\"><h5>Las <mark class=\"m-autoridad\">FUERZAS Y CUERPOS DE SEGURIDAD DEL ESTADO</mark> tienen como misión <mark class=\"m-destacable\">proteger el libre ejercicio de los derechos y libertades y garantizar la seguridad ciudadana</mark> mediante el desempeño de las siguientes funciones:</h5><ul><li><mark class=\"m-personalizado\"><u class=\"m-clave\">Velar</u></mark> por el cumplimiento de las Leyes y disposiciones generales, <mark class=\"m-destacable\">ejecutando las órdenes</mark> que reciban de las <mark class=\"m-autoridad\">Autoridades</mark>, en el ámbito de sus respectivas competencias.</li><li><mark class=\"m-personalizado\"><u class=\"m-clave\">Auxiliar y proteger</u></mark> a las <mark class=\"m-autoridad\">personas</mark> y asegurar la conservación y custodia de los bienes que se encuentren en situación de <mark class=\"m-destacable\">peligro</mark> por cualquier causa.</li><li><mark class=\"m-personalizado\"><u class=\"m-clave\">Vigilar y proteger</u></mark> los edificios e instalaciones <mark class=\"m-personalizado\"><u class=\"m-clave\">públicos</u></mark> que lo requieran.</li><li><mark class=\"m-personalizado\"><u class=\"m-clave\">Velar</u></mark> por la protección y seguridad de <mark class=\"m-personalizado\"><u class=\"m-clave\">altas personalidades</u></mark>.</li><li><mark class=\"m-personalizado\"><u class=\"m-clave\">Mantener y restablecer</u></mark>, en su caso, el orden y la seguridad ciudadana.</li><li><mark class=\"m-personalizado\"><u class=\"m-clave\">Prevenir</u></mark> la <mark class=\"m-autoridad\">comisión</mark> de actos delictivos.</li><li><mark class=\"m-personalizado\"><u class=\"m-clave\">Investigar</u></mark> los delitos para <mark class=\"m-destacable\">descubrir y detener</mark> a los presuntos culpables, asegurar los instrumentos, efectos y pruebas del delito, poniéndolos a disposición del <mark class=\"m-autoridad\">Juez o Tribunal competente</mark> y elaborar los informes técnicos y periciales procedentes.</li><li><mark class=\"m-personalizado\"><u class=\"m-clave\">Captar, recibir y analizar</u></mark> cuantos datos tengan interés para el orden y la seguridad pública, y <mark class=\"m-destacable\">estudiar, planificar y ejecutar</mark> los métodos y técnicas de prevención de la delincuencia.</li><li><mark class=\"m-personalizado\"><u class=\"m-clave\">Colaborar</u></mark> con los servicios de <mark class=\"m-personalizado\"><u class=\"m-clave\">protección civil</u></mark> en los casos de grave riesgo, catástrofe, o calamidad pública, en los términos que se establezcan en la legislación de protección civil.</li><li>Corresponde al <mark class=\"m-autoridad\">Cuerpo Nacional de Policía</mark> ejercitar dichas funciones en las <mark class=\"m-destacable\">capitales de provincia</mark> y en los términos municipales y núcleos urbanos que el <mark class=\"m-autoridad\">Gobierno</mark> determine.</li><li>La <mark class=\"m-autoridad\">Guardia Civil</mark> las <mark class=\"m-accion\">ejercerá</mark> en el <mark class=\"m-destacable\">resto del territorio nacional y su mar territorial</mark>.</li></ul></div><div class=\"vis-col\"><h5><mark class=\"m-accion\">Serán ejercidas</mark> por el <mark class=\"m-autoridad\">CUERPO NACIONAL DE POLICÍA</mark>:</h5><ul><li>La <mark class=\"m-personalizado\"><u class=\"m-clave\">expedición</u></mark> del documento nacional de identidad y de los pasaportes.</li><li>El <mark class=\"m-personalizado\"><u class=\"m-clave\">control de entrada y salida</u></mark> del territorio nacional de españoles y <mark class=\"m-autoridad\">extranjeros.</mark></li><li>Las previstas en la legislación sobre <mark class=\"m-personalizado\"><u class=\"m-clave\">extranjería, refugio y asilo, expulsión, extradición, emigración e inmigración</u></mark>.</li><li>La vigilancia e inspección del cumplimiento de la normativa en materia de <mark class=\"m-personalizado\"><u class=\"m-clave\">juego</u></mark>.</li><li>La investigación y persecución de los delitos relacionados con la <mark class=\"m-personalizado\"><u class=\"m-clave\">droga</u></mark>.</li><li><mark class=\"m-personalizado\"><u class=\"m-clave\">Colaborar y prestar auxilio a las policías de otros países</u></mark>, conforme a lo establecido en los Tratados o Acuerdos Internacionales sobre las Leyes, bajo la superior dirección del <mark class=\"m-autoridad\">Ministro del Interior</mark>.</li><li>El <mark class=\"m-personalizado\"><u class=\"m-clave\">control de las entidades y servicios privados de seguridad, vigilancia e investigación, de su personal, medios y actuaciones</u></mark>.</li><li>Aquellas otras que le atribuye la legislación vigente.</li></ul></div><div class=\"vis-col\"><h5><mark class=\"m-accion\">Serán ejercidas</mark> por la <mark class=\"m-autoridad\">GUARDIA CIVIL</mark>:</h5><ul><li>Las derivadas de la legislación vigente sobre <mark class=\"m-personalizado\"><u class=\"m-clave\">armas y explosivos</u></mark>.</li><li>El <mark class=\"m-personalizado\"><u class=\"m-clave\">resguardo</u></mark> <mark class=\"m-autoridad\"><u class=\"m-clave\">fiscal</u></mark> <mark class=\"m-autoridad\">del Estado</mark> y las actuaciones encaminadas a evitar y perseguir el <mark class=\"m-destacable\">contrabando</mark>.</li><li>La <mark class=\"m-personalizado\"><u class=\"m-clave\">vigilancia del tráfico, tránsito y transporte</u></mark> en las vías públicas <mark class=\"m-personalizado\"><u class=\"m-clave\">interurbanas</u></mark>.</li><li>La <mark class=\"m-personalizado\"><u class=\"m-clave\">custodia</u></mark> de vías de comunicación <mark class=\"m-personalizado\"><u class=\"m-clave\">terrestre, costas, fronteras, puertos, aeropuertos y centros e instalaciones</u></mark> que por su interés lo requieran.</li><li>Velar por el cumplimiento de las disposiciones que tiendan a la <mark class=\"m-personalizado\"><u class=\"m-clave\">conservación de la naturaleza y medio ambiente, de los recursos hidráulicos</u></mark>, así como de la riqueza cinegética, piscícola, forestal y de cualquier otra índole relacionada con la naturaleza.</li><li>La <mark class=\"m-personalizado\"><u class=\"m-clave\">conducción interurbana</u></mark> de presos y detenidos.</li><li>Aquellas otras que le atribuye la legislación vigente.</li></ul></div></div></div>"}],"a-14":[{"t":"COMPETENCIAS ATRIBUIDAS AL MINISTRO DE INTERIOR Y DEFENSA EN LA GUARDIA CIVIL (cuadro del temario · pág. 16 · art. 14)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⇄</i>COMPETENCIAS ATRIBUIDAS AL MINISTRO DE INTERIOR Y DEFENSA EN LA GUARDIA CIVIL (cuadro del temario · pág. 16 · art. 14)</div><div class=\"vis-comp\" style=\"--n:2\"><div class=\"vis-col\"><h5><mark class=\"m-autoridad\">MINISTRO DE INTERIOR</mark></h5><ul><li><mark class=\"m-accion\">Dispondrá</mark> todo lo concerniente a: <mark class=\"m-destacable\">servicios de la Guardia Civil relacionados con la seguridad ciudadana</mark> y demás competencias atribuidas por esta Ley.</li><li>Así como a: <mark class=\"m-personalizado\"><u class=\"m-clave\">retribuciones</u></mark> · <mark class=\"m-personalizado\"><u class=\"m-clave\">destinos</u></mark> · <mark class=\"m-personalizado\"><u class=\"m-clave\">acuartelamientos</u></mark> y <mark class=\"m-personalizado\"><u class=\"m-clave\">material</u></mark></li></ul></div><div class=\"vis-col\"><h5><mark class=\"m-autoridad\">MINISTRO DE DEFENSA</mark></h5><ul><li><mark class=\"m-accion\">Dispondrá</mark> lo concerniente: al régimen de <mark class=\"m-personalizado\"><u class=\"m-clave\">ascensos</u></mark> y <mark class=\"m-personalizado\"><u class=\"m-clave\">situaciones del personal</u></mark>,</li><li>así como a las <mark class=\"m-destacable\"><u class=\"m-clave\">misiones de carácter militar</u></mark> que se encomienden a la Guardia Civil, ejerciendo, respecto al <mark class=\"m-destacable\">voluntariado especial</mark> para la prestación del servicio militar en la misma las competencias que normativamente le correspondan.</li></ul></div></div></div><div class=\"vis\"><div class=\"vis-t\"><i>⇄</i>CONJUNTAMENTE (cuadro del temario · pág. 16 · art. 14.2)</div><div class=\"vis-comp\" style=\"--n:2\"><div class=\"vis-col\"><h5><mark class=\"m-autoridad\">Los Ministros de Defensa e Interior</mark> <mark class=\"m-accion\">dispondrán</mark> todo lo referente a la:</h5><ul><li><mark class=\"m-personalizado\"><u class=\"m-clave\">selección</u></mark></li><li><mark class=\"m-personalizado\"><u class=\"m-clave\">perfeccionamiento</u></mark></li><li><mark class=\"m-personalizado\"><u class=\"m-clave\">armamento</u></mark> y</li><li><mark class=\"m-personalizado\"><u class=\"m-clave\">despliegue territorial</u></mark></li></ul></div><div class=\"vis-col\"><h5>Y <mark class=\"m-accion\">propondrán</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">al</u></mark> <mark class=\"m-autoridad\"><u class=\"m-clave\">Gobierno</u></mark>:</h5><ul><li>el <mark class=\"m-personalizado\"><u class=\"m-clave\">nombramiento del titular de la Dirección General de la Guardia Civil</u></mark>,</li><li>así como la <mark class=\"m-personalizado\"><u class=\"m-clave\">normativa reguladora del voluntariado especial</u></mark> para la prestación del servicio militar en la misma.</li></ul></div></div></div><div class=\"vis-pie\" style=\"font-size:.86em;opacity:.85;margin-top:6px\">✎ Nota a boli del temario: junto a «selección,» has escrito «formación» (letra a boli, poco legible; en la ley el art. 14.2 dice «selección, formación, perfeccionamiento…»).</div>"}],"a-48":[{"t":"CONSEJO DE POLÍTICA DE SEGURIDAD · composición y competencias (cuadro del temario · pág. 27 · art. 48)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⇄</i>CONSEJO DE POLÍTICA DE SEGURIDAD · composición y competencias (cuadro del temario · pág. 27 · art. 48)</div><div class=\"vis-comp\" style=\"--n:2\"><div class=\"vis-col\"><h5><mark class=\"m-autoridad\">CONSEJO DE POLÍTICA DE SEGURIDAD</mark></h5><ul><li>Para <mark class=\"m-destacable\">garantizar la coordinación</mark> entre las políticas de seguridad pública del <mark class=\"m-autoridad\">Estado</mark> y de las Comunidades Autónomas se crea el <mark class=\"m-autoridad\">CONSEJO DE POLÍTICA DE SEGURIDAD</mark>, que <mark class=\"m-accion\">estará presidido</mark> por el <mark class=\"m-autoridad\">Ministro del Interior</mark> e <mark class=\"m-destacable\"><u class=\"m-clave\">integrado</u></mark> por:</li><li>- los <mark class=\"m-autoridad\">Consejeros de Interior o Gobernación de las Comunidades Autónomas</mark> y</li><li>- por un <mark class=\"m-destacable\">número igual de representantes del</mark> <mark class=\"m-autoridad\">Estado</mark> designados por el <mark class=\"m-autoridad\">Gobierno de la Nación</mark>.</li></ul></div><div class=\"vis-col\"><h5><mark class=\"m-autoridad\">COMPETENCIAS DEL CONSEJO DE POLÍTICA DE SEGURIDAD</mark></h5><ul><li><mark class=\"m-personalizado\"><u class=\"m-clave\">Aprobar</u></mark> los <mark class=\"m-destacable\">planes de coordinación</mark> en materia de seguridad y de infraestructura policial.</li><li><mark class=\"m-personalizado\"><u class=\"m-clave\">Informar</u></mark> las <mark class=\"m-destacable\">plantillas</mark> de los Cuerpos de Policía de las Comunidades Autónomas y sus modificaciones. El <mark class=\"m-autoridad\">Consejo</mark> <mark class=\"m-accion\">podrá establecer</mark> el <mark class=\"m-destacable\">número máximo</mark> de los efectivos de las plantillas.</li><li><mark class=\"m-personalizado\"><u class=\"m-clave\">Aprobar</u></mark> <mark class=\"m-destacable\">directivas y recomendaciones</mark> de carácter <mark class=\"m-destacable\">general</mark></li><li><mark class=\"m-personalizado\"><u class=\"m-clave\">Informar</u></mark> las <mark class=\"m-destacable\">disposiciones</mark> que dicten las Comunidades Autónomas, en relación con sus <mark class=\"m-destacable\">propios</mark> Cuerpos de Policía, así como la <mark class=\"m-destacable\">creación</mark> de éstos</li><li><mark class=\"m-personalizado\"><u class=\"m-clave\">Informar</u></mark> los <mark class=\"m-destacable\">convenios de cooperación</mark>, en materia de seguridad, entre el <mark class=\"m-autoridad\">Estado</mark> y las Comunidades Autónomas.</li><li>Las demás que le atribuya la legislación vigente.</li></ul></div></div></div>"}],"a-49":[{"t":"COMITÉ DE EXPERTOS · composición y funciones (cuadro del temario · pág. 27 · art. 49)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⇄</i>COMITÉ DE EXPERTOS · composición y funciones (cuadro del temario · pág. 27 · art. 49)</div><div class=\"vis-comp\" style=\"--n:2\"><div class=\"vis-col\"><h5><mark class=\"m-destacable\"><u class=\"m-clave\">COMPOSICIÓN</u></mark></h5><ul><li>Integrado por <mark class=\"m-plazo\">ocho</mark> representantes:</li><li><mark class=\"m-plazo\">cuatro</mark> del <mark class=\"m-autoridad\">Estado</mark> y</li><li><mark class=\"m-plazo\">cuatro</mark> de las <mark class=\"m-autoridad\">Comunidades Autónomas</mark>, designados estos últimos <mark class=\"m-plazo\">anualmente</mark> por los miembros del <mark class=\"m-autoridad\">Consejo de Política de Seguridad</mark> que representen a las Comunidades Autónomas.</li></ul></div><div class=\"vis-col\"><h5><mark class=\"m-destacable\"><u class=\"m-clave\">FUNCIONES</u></mark></h5><ul><li><mark class=\"m-personalizado\"><u class=\"m-clave\">Asesorar técnicamente</u></mark> al <mark class=\"m-autoridad\">CONSEJO DE POLÍTICA DE SEGURIDAD</mark> y <mark class=\"m-personalizado\"><u class=\"m-clave\">preparar los asuntos</u></mark> que posteriormente vayan a ser debatidos en el Pleno del mismo</li><li><mark class=\"m-destacable\"><u class=\"m-clave\">FUNCIONES CON CARÁCTER ESPECÍFICO</u></mark>:</li><li><mark class=\"m-personalizado\"><u class=\"m-clave\">Elaborar y proponer</u></mark> fórmulas de coordinación.</li><li><mark class=\"m-personalizado\"><u class=\"m-clave\">Preparar</u></mark> acuerdos de cooperación.</li><li><mark class=\"m-personalizado\"><u class=\"m-clave\">Proponer</u></mark> programas de formación y perfeccionamiento de las Policías.</li><li><mark class=\"m-personalizado\"><u class=\"m-clave\">Elaborar</u></mark> planes de actuación conjunta.</li></ul></div></div></div>"}],"a-50":[{"t":"ÓRGANOS DE COORDINACIÓN ENTRE LAS FFCCSE Y LAS CCAA (cuadro del temario · pág. 28 · arts. 48-50)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>ÓRGANOS DE COORDINACIÓN ENTRE LAS FFCCSE Y LAS CCAA (cuadro del temario · pág. 28 · arts. 48-50)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-autoridad\"><u class=\"m-clave\">ÓRGANOS</u></mark> <mark class=\"m-destacable\"><u class=\"m-clave\">DE COORDINACIÓN ENTRE LAS FFCCSE Y LAS CCAA</u></mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\"><mark class=\"m-autoridad\">CONSEJO DE POLÍTICA DE SEGURIDAD</mark><div class=\"vis-sub\"></div></div><div class=\"vis-rama\"><mark class=\"m-autoridad\">COMITÉ DE EXPERTOS</mark><div class=\"vis-sub\"></div></div><div class=\"vis-rama\"><mark class=\"m-autoridad\">JUNTAS DE SEGURIDAD</mark><div class=\"vis-sub\"></div></div></div></div></div><div class=\"vis-pie\" style=\"font-size:.86em;opacity:.85;margin-top:6px\">✎ En tu esquema una flecha doble une Consejo de Política de Seguridad con Comité de Expertos, y otra flecha lleva a las Juntas de Seguridad.</div>"}],"c-3":[{"t":"ÓRGANOS DE COORDINACIÓN ENTRE LAS FFCCSE Y LOS MUNICIPIOS (cuadro del temario · pág. 49 · art. 3)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>ÓRGANOS DE COORDINACIÓN ENTRE LAS FFCCSE Y LOS MUNICIPIOS (cuadro del temario · pág. 49 · art. 3)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-autoridad\"><u class=\"m-clave\">ÓRGANOS</u></mark> <mark class=\"m-destacable\"><u class=\"m-clave\">DE COORDINACIÓN ENTRE LAS FFCCSE Y LOS MUNICIPIOS</u></mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\"><mark class=\"m-autoridad\">JUNTAS LOCALES DE SEGURIDAD</mark><div class=\"vis-sub\"><span>(En <mark class=\"m-destacable\">municipios o agrupaciones de municipios</mark> que tengan <mark class=\"m-destacable\">Cuerpo de Policía propio</mark>).</span></div></div><div class=\"vis-rama\"><mark class=\"m-autoridad\">COMISIÓN LOCAL DE SEGURIDAD</mark><div class=\"vis-sub\"><span>(Donde <u class=\"m-clave\">no</u> exista <mark class=\"m-destacable\">Cuerpo de Policía Local</mark>).</span></div></div></div></div></div><div class=\"vis-pie\" style=\"font-size:.86em;opacity:.85;margin-top:6px\">✎ En tu esquema una flecha doble une las dos cajas (Junta Local de Seguridad ↔ Comisión Local de Seguridad).</div>"}],"c-19":[{"t":"ÓRGANOS RELACIONADOS CON LAS JUNTAS LOCALES DE SEGURIDAD (cuadro del temario · pág. 55 · arts. 12-19)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>ÓRGANOS RELACIONADOS CON LAS JUNTAS LOCALES DE SEGURIDAD (cuadro del temario · pág. 55 · arts. 12-19)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-autoridad\"><u class=\"m-clave\">ÓRGANOS</u></mark> <mark class=\"m-destacable\"><u class=\"m-clave\">RELACIONADOS CON LAS JUNTAS LOCALES DE SEGURIDAD</u></mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\"><mark class=\"m-destacable\"><u class=\"m-clave\">COMISIONES TÉCNICAS</u></mark><div class=\"vis-sub\"><span><mark class=\"m-autoridad\">(Órgano</mark> de asesoramiento)</span></div></div><div class=\"vis-rama\"><mark class=\"m-destacable\"><u class=\"m-clave\">CONSEJOS LOCALES DE SEGURIDAD</u></mark><div class=\"vis-sub\"><span><mark class=\"m-autoridad\">(Órgano</mark> de participación ciudadana)</span></div></div><div class=\"vis-rama\"><mark class=\"m-destacable\"><u class=\"m-clave\">COMISIONES DE COORDINACIÓN POLICIAL</u></mark><div class=\"vis-sub\"></div></div><div class=\"vis-rama\"><mark class=\"m-destacable\"><u class=\"m-clave\">JUNTAS DE SEGURIDAD DE DISTRITO</u></mark><div class=\"vis-sub\"></div></div></div></div></div><div class=\"vis-pie\" style=\"font-size:.86em;opacity:.85;margin-top:6px\">✎ Notas a boli del temario: bajo «Comisiones de coordinación policial» has escrito «(Jefes Policiales)»; y debajo del cuadro: «Comisiones Locales de Seguridad: sin P. Lo.» (sin Policía Local).</div>"}],"e-5":[{"t":"INTERPOL · organigrama (cuadro del temario · pág. 58 · art. 5)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>INTERPOL · organigrama (cuadro del temario · pág. 58 · art. 5)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-autoridad\"><u class=\"m-clave\">INTERPOL</u></mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\"><mark class=\"m-autoridad\">ASAMBLEA GENERAL</mark><div class=\"vis-sub\"></div></div><div class=\"vis-rama\"><mark class=\"m-autoridad\">COMITÉ EJECUTIVO</mark><div class=\"vis-sub\"></div></div><div class=\"vis-rama\"><mark class=\"m-autoridad\">SECRETARÍA GENERAL</mark><div class=\"vis-sub\"></div></div><div class=\"vis-rama\"><mark class=\"m-autoridad\">OFICINAS CENTRALES NACIONALES</mark><div class=\"vis-sub\"></div></div><div class=\"vis-rama\"><mark class=\"m-autoridad\">ASESORES</mark><div class=\"vis-sub\"></div></div></div></div></div>"}],"e-15":[{"t":"COMITÉ EJECUTIVO · composición (cuadro del temario · pág. 60 · art. 15)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>COMITÉ EJECUTIVO · composición (cuadro del temario · pág. 60 · art. 15)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-autoridad\">COMITÉ EJECUTIVO</mark> · <mark class=\"m-destacable\"><u class=\"m-clave\">COMPOSICIÓN</u></mark>: <mark class=\"m-plazo\">Trece</mark> miembros:</div><div class=\"vis-ramas\"><div class=\"vis-rama\">el <mark class=\"m-autoridad\">Presidente de la Organización</mark><div class=\"vis-sub\"></div></div><div class=\"vis-rama\"><mark class=\"m-plazo\">tres</mark> <mark class=\"m-autoridad\">Vicepresidentes</mark><div class=\"vis-sub\"></div></div><div class=\"vis-rama\"><mark class=\"m-plazo\">nueve</mark> <mark class=\"m-autoridad\">Vocales</mark><div class=\"vis-sub\"></div></div></div></div></div>"}],"d-3":[{"t":"DELITOS CONEXOS (cuadro del temario · págs. 70-71 · art. 3.2)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>DELITOS CONEXOS (cuadro del temario · págs. 70-71 · art. 3.2)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\">Además de lo indicado en el apartado 1, <mark class=\"m-destacable\">los</mark> <mark class=\"m-autoridad\">objetivos de Europol</mark> <mark class=\"m-accion\">abarcarán</mark> <mark class=\"m-personalizado\">también</mark> <mark class=\"m-destacable\">los delitos conexos</mark>. <mark class=\"m-accion\">Se considerarán</mark> delitos conexos:</div><div class=\"vis-ramas\"><div class=\"vis-rama\"><mark class=\"m-destacable\">a) los delitos</mark> cometidos <mark class=\"m-personalizado\">con objeto</mark> de procurarse <mark class=\"m-personalizado\">los medios</mark> para <mark class=\"m-personalizado\">perpetrar actos</mark> en los que <mark class=\"m-autoridad\">Europol</mark> <mark class=\"m-personalizado\">sea competente</mark>;</div><div class=\"vis-rama\"><mark class=\"m-destacable\">b) los delitos</mark> cometidos para <mark class=\"m-personalizado\">facilitar o perpetrar actos</mark> en los que <mark class=\"m-autoridad\">Europol</mark> <mark class=\"m-personalizado\">sea competente</mark>;</div><div class=\"vis-rama\"><mark class=\"m-destacable\">c) los delitos</mark> cometidos para <mark class=\"m-personalizado\">asegurar la impunidad</mark> de quienes cometen estos actos en los que <mark class=\"m-autoridad\">Europol</mark> <mark class=\"m-personalizado\">sea competente</mark>.</div></div></div><div class=\"vis-pie\" style=\"font-size:.86em;opacity:.85;margin-top:6px\">✎ a) y b) con tu fosforito (pág. 70); c) (pág. 71) va impreso sin fosforito: color por método.</div></div>"}],"d-9":[{"t":"ESTRUCTURA ADMINISTRATIVA Y DE GESTIÓN DE EUROPOL (organigrama del temario · pág. 77 · art. 9)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>ESTRUCTURA ADMINISTRATIVA Y DE GESTIÓN DE EUROPOL (organigrama del temario · pág. 77 · art. 9)</div><div class=\"vis-lit\" style=\"margin:4px 0 8px\">La <mark class=\"m-autoridad\">estructura</mark> <mark class=\"m-destacable\">administrativa y de gestión</mark> de <mark class=\"m-autoridad\">Europol</mark> estará compuesta por:<br><mark class=\"m-destacable\">a)</mark> un <mark class=\"m-autoridad\">Consejo de Administración</mark>;<br><mark class=\"m-destacable\">b)</mark> un <mark class=\"m-autoridad\">director ejecutivo</mark>;<br><mark class=\"m-destacable\">c)</mark> <u class=\"m-clave\">en su caso</u>, otro <mark class=\"m-autoridad\">órgano consultivo</mark> <u class=\"m-clave\">establecido</u> por el <mark class=\"m-autoridad\">Consejo de Administración</mark> <u class=\"m-clave\">de conformidad</u> con el artículo <mark class=\"m-personalizado\">11, apartado 1, letra s)</mark>.</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-autoridad\">EUROPOL</mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\"><mark class=\"m-autoridad\">CONSEJO DE ADMINISTRACIÓN</mark></div><div class=\"vis-rama\"><mark class=\"m-autoridad\">DIRECTOR EJECUTIVO</mark></div><div class=\"vis-rama\"><mark class=\"m-autoridad\">ÓRGANO CONSULTIVO</mark> (en su caso)</div></div></div><div class=\"vis-pie\" style=\"font-size:.86em;opacity:.85;margin-top:6px\">✎ recuadros azules a boli en «en su caso», «establecido» y «de conformidad»; marca a boli junto al encabezado.</div></div>"}],"d-10":[{"t":"CONSEJO DE ADMINISTRACIÓN (cuadro del temario · pág. 78 · art. 10)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>▦</i>CONSEJO DE ADMINISTRACIÓN (cuadro del temario · pág. 78 · art. 10)</div><div class=\"vis-tabla\"><div class=\"vt-cab\"><span>Concepto</span><span>Contenido</span></div><div class=\"vt-nodo\"><div class=\"vt-et o\">COMPOSICIÓN</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">- <mark class=\"m-destacable\">un</mark> representante de cada <mark class=\"m-autoridad\">Estado miembro</mark>. ①</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">- <mark class=\"m-destacable\">un</mark> representante de la <mark class=\"m-autoridad\">Comisión</mark>. ①</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">• <u class=\"m-clave\">Todos</u> ellos <mark class=\"m-accion\">tendrán</mark> <mark class=\"m-destacable\">derecho a voto</mark>.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et o\"><mark class=\"m-accion\">SE TENDRÁ</mark> EN CUENTA</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">• El <mark class=\"m-destacable\">principio de una representación por sexos equilibrada</mark>.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et o\">DURACIÓN MANDATO</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">• <mark class=\"m-plazo\">Cuatro años</mark>.</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">• El mandato <mark class=\"m-accion\">será</mark> <mark class=\"m-plazo\">prorrogable</mark>.</div></div></div></div></div><div class=\"vis-pie\" style=\"font-size:.86em;opacity:.85;margin-top:6px\">✎ a boli: círculos «1» junto a cada representante, «P» en el margen y un círculo con «Ex…» (lectura dudosa: EXOF/EX); recuadro azul en «Todos».</div></div>"}],"d-17":[{"t":"FUENTES DE INFORMACIÓN (cuadro del temario · pág. 83 · art. 17.1)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>FUENTES DE INFORMACIÓN (cuadro del temario · pág. 83 · art. 17.1)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-autoridad\">Europol</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">solamente</u></mark> <mark class=\"m-accion\">podrá tratar</mark> la <mark class=\"m-personalizado\">información</mark> que le haya <mark class=\"m-personalizado\">sido facilitada por</mark>:</div><div class=\"vis-ramas\"><div class=\"vis-rama\"><mark class=\"m-destacable\">a)</mark> los <mark class=\"m-autoridad\">Estados miembros</mark>, <u class=\"m-clave\">de conformidad</u> con su <mark class=\"m-personalizado\">Derecho nacional</mark> y con el artículo <mark class=\"m-personalizado\">7</mark>;</div><div class=\"vis-rama\"><mark class=\"m-destacable\">b)</mark> <mark class=\"m-autoridad\">organismos de la Unión, países terceros y organizaciones internacionales</mark>, <u class=\"m-clave\">de conformidad</u> con el <mark class=\"m-personalizado\">capítulo V</mark>;</div><div class=\"vis-rama\"><mark class=\"m-destacable\">c)</mark> por <mark class=\"m-autoridad\">entidades privadas y particulares</mark> de <u class=\"m-clave\">conformidad</u> con el <mark class=\"m-personalizado\">capítulo V</mark>.</div></div></div><div class=\"vis-pie\" style=\"font-size:.86em;opacity:.85;margin-top:6px\">✎ recuadros azules a boli en «de conformidad» y marca «V» sobre «y».</div></div>"}],"d-29":[{"t":"CÓDIGOS DE EVALUACIÓN DE FUENTES (art. 29 · pág. 99 · apartados 1 y 2)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⇄</i>CÓDIGOS DE EVALUACIÓN DE FUENTES (art. 29 · pág. 99 · apartados 1 y 2)</div><div class=\"vis-comp\" style=\"--n:2\"><div class=\"vis-col\"><h5><mark class=\"m-destacable\">1. FIABILIDAD DE LA FUENTE · A, B, C, X</mark></h5><ul><li>La <mark class=\"m-destacable\">fiabilidad de la fuente de la información</mark> procedente de un <mark class=\"m-autoridad\">Estado</mark> miembro <mark class=\"m-accion\">será valorada</mark> en la <mark class=\"m-personalizado\">medida de lo posible</mark> por el <mark class=\"m-autoridad\">Estado miembro que haya facilitado los datos</mark>, utilizando los siguientes <mark class=\"m-destacable\">códigos</mark> de <mark class=\"m-destacable\">evaluación de fuentes</mark>:</li><li><mark class=\"m-destacable\">A)</mark>: cuando <u class=\"m-clave\">no quepa duda</u> sobre la autenticidad, veracidad y competencia de la fuente o si la información es facilitada por una fuente que haya resultado ser fiable en todos los casos;</li><li><mark class=\"m-destacable\">B)</mark>: cuando la información sea facilitada por una fuente que haya resultado <mark class=\"m-destacable\">ser fiable en la mayoría de los casos</mark>;</li><li><mark class=\"m-destacable\">C)</mark>: cuando la información sea facilitada por una fuente que haya resultado <mark class=\"m-destacable\">ser poco fiable en la mayoría de los casos</mark>;</li><li><mark class=\"m-destacable\">X)</mark>: cuando <mark class=\"m-destacable\">no pueda determinarse la fiabilidad de la fuente</mark>.</li></ul></div><div class=\"vis-col\"><h5><mark class=\"m-destacable\">2. EXACTITUD DE LA INFORMACIÓN · 1, 2, 3, 4</mark></h5><ul><li>La <mark class=\"m-destacable\">exactitud de la información</mark> procedente de un <mark class=\"m-autoridad\">Estado</mark> miembro <mark class=\"m-accion\">será valorada</mark> en la <mark class=\"m-personalizado\">medida de lo posible</mark> por el <mark class=\"m-autoridad\">Estado miembro que haya facilitado los datos</mark> utilizando los siguientes <mark class=\"m-destacable\">códigos de evaluación de fuentes</mark>:</li><li><mark class=\"m-destacable\">1)</mark>: información sobre cuya exactitud <u class=\"m-clave\">no</u> exista duda alguna;</li><li><mark class=\"m-destacable\">2)</mark>: información conocida personalmente por la fuente, pero <u class=\"m-clave\">no</u> conocida personalmente por el funcionario que la transmite;</li><li><mark class=\"m-destacable\">3)</mark>: información <u class=\"m-clave\">no</u> conocida personalmente por la fuente, pero corroborada por otra información ya registrada;</li><li><mark class=\"m-destacable\">4)</mark>: información <u class=\"m-clave\">no</u> conocida personalmente por la fuente y que <u class=\"m-clave\">no</u> puede ser corroborada.</li></ul></div></div><div class=\"vis-pie\" style=\"font-size:.86em;opacity:.85;margin-top:6px\">✎ apartado 1 con tu fosforito (naranja en «fiabilidad…», «códigos», A-B-C-X); apartado 2 (códigos 1-4) impreso sin fosforito: color por método. Círculo a boli en el «1.»</div></div>"}],"d-31":[{"t":"REEXAMEN DE LA CONSERVACIÓN: 3 AÑOS (cuadro del temario · pág. 101 · art. 31.2)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⏱</i>REEXAMEN DE LA CONSERVACIÓN: 3 AÑOS (cuadro del temario · pág. 101 · art. 31.2)</div><div class=\"vis-plazos\"><div class=\"vis-plazo\"><span class=\"n\">3 años</span><mark class=\"m-autoridad\">Europol</mark> <mark class=\"m-accion\">reexaminará</mark>, <u class=\"m-clave\">en todo caso</u>, <mark class=\"m-personalizado\">la necesidad de prolongar el período de conservación</mark> a <mark class=\"m-plazo\">más tardar tres años</mark> después del comienzo del tratamiento inicial de los datos personales.</div><div class=\"vis-plazo\"><span class=\"n\">+3 años</span><mark class=\"m-autoridad\">Europol</mark> <mark class=\"m-accion\">podrá decidir prolongar</mark> el período de conservación de los datos personales <mark class=\"m-personalizado\">hasta el reexamen siguiente</mark>, que <mark class=\"m-accion\">tendrá</mark> lugar transcurrido <mark class=\"m-plazo\">un nuevo período de tres años</mark>, si sigue siendo necesario <mark class=\"m-personalizado\">para el desempeño de sus tareas</mark>. Las razones para prolongar el período de conservación <mark class=\"m-accion\">deberán justificarse y registrarse</mark>.</div><div class=\"vis-plazo\"><span class=\"n\">Sin decisión</span>De <mark class=\"m-personalizado\">no tomarse una decisión</mark> sobre la prolongación de la conservación de los datos personales, estos <mark class=\"m-accion\">se cancelarán</mark> <mark class=\"m-destacable\">automáticamente</mark> <mark class=\"m-plazo\">al cabo de tres años</mark>.</div></div><div class=\"vis-pie\" style=\"font-size:.86em;opacity:.85;margin-top:6px\">✎ pin «R23» a boli junto al apartado 1; marca «R» junto al «2.».</div></div>"}],"d-54":[{"t":"MANDATO DEL DIRECTOR EJECUTIVO (cuadros del temario · pág. 117 · art. 54.3 y 54.4)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>➜</i>MANDATO DEL DIRECTOR EJECUTIVO (cuadros del temario · pág. 117 · art. 54.3 y 54.4)</div><div class=\"vis-flujo\"><div class=\"vis-paso o\"><span class=\"et\">54.3 · DURACIÓN Y EVALUACIÓN</span><mark class=\"m-destacable\">El mandato del director ejecutivo</mark> <mark class=\"m-accion\">tendrá una</mark> <mark class=\"m-plazo\">duración de cuatro años</mark>. <mark class=\"m-personalizado\">Al final de ese período</mark>, la <mark class=\"m-autoridad\">Comisión</mark>, <mark class=\"m-destacable\">en asociación</mark> con el <mark class=\"m-autoridad\">Consejo de Administración</mark>, <mark class=\"m-accion\">llevará</mark> <mark class=\"m-destacable\">a cabo</mark>:<br><mark class=\"m-destacable\">a)</mark> <mark class=\"m-personalizado\">una valoración</mark> teniendo en cuenta una evaluación de la actuación del director ejecutivo, y<br><mark class=\"m-destacable\">b)</mark> <mark class=\"m-personalizado\">las futuras tareas y retos</mark> de <mark class=\"m-autoridad\">Europol.</mark></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso v\"><span class=\"et\">54.4 · PRÓRROGA</span>El <mark class=\"m-autoridad\">Consejo</mark>, <mark class=\"m-destacable\">a propuesta</mark> del <mark class=\"m-autoridad\">Consejo de Administración</mark>, que <mark class=\"m-accion\">tendrá</mark> en cuenta la valoración contemplada en el apartado 3, <mark class=\"m-accion\">podrá prorrogar</mark> el <mark class=\"m-personalizado\">mandato del director ejecutivo</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">solo una vez</u></mark> <mark class=\"m-plazo\">y por un período máximo de cuatro años</mark>.</div></div><div class=\"vis-pie\" style=\"font-size:.86em;opacity:.85;margin-top:6px\">✎ círculos a boli «EXO» junto a cada recuadro (apartados 3 y 4); recuadro azul en «solo una vez (y)».</div></div>"}],"d-60":[{"t":"APROBACIÓN DE LA GESTIÓN DEL DIRECTOR EJECUTIVO (cuadro del temario · pág. 120 · art. 60.10)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>➜</i>APROBACIÓN DE LA GESTIÓN DEL DIRECTOR EJECUTIVO (cuadro del temario · pág. 120 · art. 60.10)</div><div class=\"vis-flujo\"><div class=\"vis-paso o\"><span class=\"et\">60.10</span>El <mark class=\"m-autoridad\">Parlamento Europeo</mark>, previa recomendación del <mark class=\"m-autoridad\">Consejo</mark> por <mark class=\"m-plazo\">mayoría cualificada</mark>, <mark class=\"m-accion\">aprobará</mark>, <mark class=\"m-plazo\">antes del 15 de mayo del ejercicio N + 2</mark>, <mark class=\"m-destacable\">la gestión del director ejecutivo</mark> con respecto a la ejecución del presupuesto del ejercicio presupuestario del año N.</div></div><div class=\"vis-pie\" style=\"font-size:.86em;opacity:.85;margin-top:6px\">✎ cuadro impreso sin fosforito (solo negrita/subrayado de imprenta): color por método.</div></div>"}],"d-64":[{"t":"RÉGIMEN LINGÜÍSTICO INTERNO (cuadro del temario · pág. 121 · art. 64.2)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>➜</i>RÉGIMEN LINGÜÍSTICO INTERNO (cuadro del temario · pág. 121 · art. 64.2)</div><div class=\"vis-flujo\"><div class=\"vis-paso o\"><span class=\"et\">64.2</span>El <mark class=\"m-autoridad\">Consejo de Administración</mark> <mark class=\"m-accion\">decidirá</mark> por <mark class=\"m-destacable\">mayoría de dos tercios</mark> de sus miembros <mark class=\"m-personalizado\">el régimen lingüístico</mark> interno de <mark class=\"m-autoridad\">Europol</mark>.</div></div><div class=\"vis-pie\" style=\"font-size:.86em;opacity:.85;margin-top:6px\">✎ tu fosforito: lila en «Consejo de Administración decidirá», naranja en «mayoría de dos tercios», amarillo en «el régimen lingüístico».</div></div>"}],"a-3":[{"t":"ANEXO I · LISTA DE FORMAS DE DELINCUENCIA A LAS QUE HACE REFERENCIA EL ARTÍCULO 3, APARTADO 1 (pág. 127)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⇄</i>ANEXO I · LISTA DE FORMAS DE DELINCUENCIA A LAS QUE HACE REFERENCIA EL ARTÍCULO 3, APARTADO 1 (pág. 127)</div><div class=\"vis-comp\" style=\"--n:2\"><div class=\"vis-col\"><h5><mark class=\"m-destacable\">Formas de delincuencia (1-15)</mark></h5><ul><li>- <mark class=\"m-destacable\">terrorismo</mark>,</li><li>- <mark class=\"m-destacable\">delincuencia</mark> organizada,</li><li>- <mark class=\"m-destacable\">tráfico</mark> de estupefacientes,</li><li>- <mark class=\"m-destacable\">actividades</mark> de blanqueo de capitales,</li><li>- <mark class=\"m-destacable\">delitos</mark> relacionados con materiales nucleares o sustancias radiactivas,</li><li>- <mark class=\"m-destacable\">tráfico</mark> de inmigrantes,</li><li>- <mark class=\"m-destacable\">trata</mark> de seres humanos,</li><li>- <mark class=\"m-destacable\">delincuencia</mark> relacionada con el tráfico de vehículos robados,</li><li>- <mark class=\"m-destacable\">homicidio</mark> voluntario y agresión con lesiones graves,</li><li>- <mark class=\"m-destacable\">tráfico</mark> ilícito de <mark class=\"m-autoridad\">órganos</mark> y tejidos humanos,</li><li>- <mark class=\"m-destacable\">secuestro</mark>, retención ilegal y toma de rehenes,</li><li>- <mark class=\"m-destacable\">racismo</mark> y xenofobia,</li><li>- <mark class=\"m-destacable\">robo</mark> y hurto con agravantes,</li><li>- <mark class=\"m-destacable\">tráfico</mark> ilícito de bienes culturales, incluidas las antigüedades y obras de arte,</li><li>- <mark class=\"m-destacable\">fraude</mark> y estafa,</li></ul></div><div class=\"vis-col\"><h5><mark class=\"m-destacable\">Formas de delincuencia (16-30)</mark></h5><ul><li>- <mark class=\"m-destacable\">delitos</mark> contra los intereses financieros de la Unión,</li><li>- <mark class=\"m-destacable\">operaciones</mark> con información privilegiada y manipulación del mercado,</li><li>- <mark class=\"m-destacable\">chantaje</mark> y extorsión,</li><li>- <mark class=\"m-destacable\">violación</mark> de derechos de propiedad industrial y falsificación de mercancías,</li><li>- <mark class=\"m-destacable\">falsificación</mark> de documentos administrativos y tráfico de documentos administrativos falsos,</li><li>- <mark class=\"m-destacable\">falsificación</mark> de moneda, falsificación de medios de pago,</li><li>- <mark class=\"m-destacable\">delito</mark> informático,</li><li>- <mark class=\"m-destacable\">corrupción</mark>,</li><li>- <mark class=\"m-destacable\">tráfico</mark> ilícito de armas, municiones y explosivos,</li><li>- <mark class=\"m-destacable\">tráfico</mark> ilícito de especies animales protegidas,</li><li>- <mark class=\"m-destacable\">tráfico</mark> ilícito de especies y variedades vegetales protegidas,</li><li>- <mark class=\"m-destacable\">delitos</mark> contra el medio ambiente, incluida la contaminación procedente de buques,</li><li>- <mark class=\"m-destacable\">tráfico</mark> ilícito de sustancias hormonales y otros factores de crecimiento,</li><li>- <mark class=\"m-destacable\">abusos</mark> sexuales y explotación sexual, incluido el material sobre abuso de <mark class=\"m-autoridad\">menores</mark> y la captación de <mark class=\"m-autoridad\">menores</mark> con fines sexuales,</li><li>- <mark class=\"m-destacable\">genocidio</mark>, crímenes de lesa humanidad y crímenes de guerra.</li></ul></div></div><div class=\"vis-pie\" style=\"font-size:.86em;opacity:.85;margin-top:6px\">✎ página impresa sin fosforito ni boli: solo se resalta (naranja) la primera palabra de cada forma, por método.</div></div>"}]};